// Deterministic Tothal-shift outdoor ruins generated by the exact V50
// Debris-ifier. The resulting hobunji_locale records enter the ordinary
// wilderness locale placement pipeline; no second placement system exists.
(() => {
  'use strict';
  const SOURCE_SHA = '038a5d54c66b0ae2a9ceeb66967b9e5c32b616040f40b503eec59d5331885f40';
  let frame = null, apiPromise = null;

  function wait(ms) { return new Promise(resolve => setTimeout(resolve, ms)); }
  async function api() {
    if (apiPromise) return apiPromise;
    apiPromise = (async () => {
      frame = document.createElement('iframe');
      frame.id = 'randomOutdoorRuinGeneratorFrame'; frame.tabIndex = -1; frame.setAttribute('aria-hidden', 'true');
      frame.style.cssText = 'position:fixed;left:-10000px;top:-10000px;width:16px;height:16px;opacity:0;pointer-events:none;border:0;z-index:-1';
      frame.src = `tools/debris-ifier/index.html?runtimeOutdoor=1&t=${Date.now()}`;
      document.body.appendChild(frame);
      const started = performance.now();
      while (performance.now() - started < 20000) {
        const candidate = frame.contentWindow?.DebrisifierV50;
        if (candidate?.sourceSha256 === SOURCE_SHA && candidate.generateOutdoorLocale) return candidate;
        await wait(40);
      }
      throw new Error('V50 outdoor ruin generator timed out');
    })();
    return apiPromise;
  }

  async function generateLocaleDefs(seedPrefix, count = 4) {
    const generator = await api();
    const locales = [];
    for (let index = 0; index < Math.max(1, Math.min(8, count)); index++) {
      const generated = await generator.generateOutdoorLocale({ seed:`${seedPrefix}|outdoor-ruin-${index + 1}`, size:index % 3 === 0 ? 'large' : 'medium', density:58 + (index % 3) * 7, sunkenChance:18 });
      const locale = generated.locale;
      locale.id = `locale_random_outdoor_ruin_${index + 1}`;
      locale.name = `Weathered Ruins ${index + 1}`;
      locale.singleton = true;
      locale.meta = { ...(locale.meta || {}), previewOnly:false, runtimeGenerated:true, sourceSha256:SOURCE_SHA };
      locale.placement = { ...(locale.placement || {}), mode:'fixed', maxInstances:1, groundOnly:true, requiresFlatGround:true, clearanceTiles:2, minDistanceFromEntry:8 };
      locales.push(locale);
    }
    return locales;
  }

  window.RandomOutdoorRuins = Object.freeze({ sourceSha256:SOURCE_SHA, generateLocaleDefs });
})();
